void* parsed_archc_isa::dispatch() {
  //!Updating Regs for behavioral simulation.
  if (ac_qk.need_sync()) {
    ac_qk.sync();
  }
  if( ac_pc >= dec_cache_size){
    cerr << "ArchC: Address out of bounds (pc=0x" << hex << ac_pc << ")." << endl;
    stop();
    longjmp(ac_env, AC_ACTION_STOP);
  }
  ac_instr_counter++;
  unsigned ins_id;
  instr_dec = (DEC_CACHE + (ac_pc));
  if ( !instr_dec->valid ){
    unsigned* ins_cache;
    decode_pc = ac_pc;
    quant = 0;
    ins_cache = (ISA.decoder)->Decode(reinterpret_cast<unsigned char*>(buffer), quant);
    instr_dec->valid = true;
    instr_dec->id = ins_cache ? ins_cache[IDENT]: 0;
    instr_dec->end_rot = IntRoutine[instr_dec->id];
    switch (ISA.instr_format_table[instr_dec->id]) {
      case 1:
        instr_dec->F_Type_VV.funct6 = ins_cache[1];
        instr_dec->F_Type_VV.vm = ins_cache[2];
        instr_dec->F_Type_VV.vs2 = ins_cache[3];
        instr_dec->F_Type_VV.vs1 = ins_cache[4];
        instr_dec->F_Type_VV.funct3 = ins_cache[5];
        instr_dec->F_Type_VV.vd = ins_cache[6];
        instr_dec->F_Type_VV.opcode = ins_cache[7];
      break;
      case 2:
        instr_dec->F_Type_VX.funct6 = ins_cache[1];
        instr_dec->F_Type_VX.vm = ins_cache[2];
        instr_dec->F_Type_VX.vs2 = ins_cache[3];
        instr_dec->F_Type_VX.rs1 = ins_cache[4];
        instr_dec->F_Type_VX.funct3 = ins_cache[5];
        instr_dec->F_Type_VX.vd = ins_cache[6];
        instr_dec->F_Type_VX.opcode = ins_cache[7];
      break;
      case 3:
        instr_dec->F_Type_VI.funct6 = ins_cache[1];
        instr_dec->F_Type_VI.vm = ins_cache[2];
        instr_dec->F_Type_VI.vs2 = ins_cache[3];
        instr_dec->F_Type_VI.imm = ins_cache[4];
        instr_dec->F_Type_VI.funct3 = ins_cache[5];
        instr_dec->F_Type_VI.vd = ins_cache[6];
        instr_dec->F_Type_VI.opcode = ins_cache[7];
      break;
      case 4:
        instr_dec->F_Type_MVV.funct6 = ins_cache[1];
        instr_dec->F_Type_MVV.vm = ins_cache[2];
        instr_dec->F_Type_MVV.vs2 = ins_cache[3];
        instr_dec->F_Type_MVV.vs1 = ins_cache[4];
        instr_dec->F_Type_MVV.funct3 = ins_cache[5];
        instr_dec->F_Type_MVV.vd = ins_cache[6];
        instr_dec->F_Type_MVV.opcode = ins_cache[7];
      break;
      default:
        cerr << "ArchC Error: Unidentified instruction. " << endl;
        cerr << "PC = " << hex << ac_pc << dec << endl;
        stop();
        longjmp(ac_env, AC_ACTION_STOP);
    }
  }
  ins_id = instr_dec->id;

  ISA.cur_instr_id = ins_id;
  return instr_dec->end_rot;
}

